1	package tracepath
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"sort"
9		"strconv"
10		"strings"
11	)
12	
13	// Server adapts a Service onto net/http. It owns routing, request decoding and
14	// the documented error shape; every rule lives in the service layer.
15	type Server struct {
16		service *Service
17	}
18	
19	// NewServer builds the HTTP handler for one service.
20	func NewServer(service *Service) *Server {
21		return &Server{service: service}
22	}
23	
24	func (s *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
25		status, response, err := s.dispatch(request, splitPath(request.URL.Path))
26		if err != nil {
27			writeError(writer, err)
28			return
29		}
30		writeJSON(writer, status, response)
31	}
32	
33	func (s *Server) dispatch(request *http.Request, parts []string) (int, any, error) {
34		method := request.Method
35		switch {
36		case method == http.MethodGet && len(parts) == 1 && parts[0] == "health":
37			if err := requireQuery(request); err != nil {
38				return 0, nil, err
39			}
40			return http.StatusOK, map[string]any{"status": "ok"}, nil
41	
42		case method == http.MethodPost && len(parts) == 1 && parts[0] == "spans":
43			body, err := readJSONBody(request)
44			if err != nil {
45				return 0, nil, err
46			}
47			response, err := s.service.IngestSpan(body, request.Header.Get("Idempotency-Key"))
48			return http.StatusCreated, response, err
49	
50		case method == http.MethodGet && len(parts) == 1 && parts[0] == "traces":
51			if err := requireQuery(request, "service", "limit", "q", "operation", "status",
52				"start_from", "start_to", "min_duration_ns", "max_duration_ns", "complete", "valid",
53				"service_path"); err != nil {
54				return 0, nil, err
55			}
56			filter, err := TraceFilterFromQuery(request.URL.Query())
57			if err != nil {
58				return 0, nil, err
59			}
60			limit := 100
61			if raw := request.URL.Query().Get("limit"); raw != "" {
62				parsed, err := strconv.Atoi(raw)
63				if err != nil {
64					return 0, nil, ValidationError("limit must be an integer")
65				}
66				limit = parsed
67			}
68			response, err := s.service.ListTraces(filter, limit)
69			return http.StatusOK, response, err
70	
71		case method == http.MethodGet && len(parts) == 2 && parts[0] == "traces":
72			if err := requireQuery(request); err != nil {
73				return 0, nil, err
74			}
75			response, err := s.service.GetTrace(parts[1])
76			return http.StatusOK, response, err
77	
78		case method == http.MethodGet && len(parts) == 3 && parts[0] == "traces" && parts[2] == "critical-path":
79			if err := requireQuery(request); err != nil {
80				return 0, nil, err
81			}
82			response, err := s.service.CriticalPath(parts[1])
83			return http.StatusOK, response, err
84	
85		case method == http.MethodGet && len(parts) == 2 && parts[0] == "services" && parts[1] == "graph":
86			if err := requireQuery(request, "trace_id"); err != nil {
87				return 0, nil, err
88			}
89			response, err := s.service.ServiceGraph(strings.TrimSpace(request.URL.Query().Get("trace_id")))
90			return http.StatusOK, response, err
91		}
92		return 0, nil, NotFoundError("route was not found")
93	}
94	
95	func readJSONBody(request *http.Request) ([]byte, error) {
96		contentType := request.Header.Get("Content-Type")
97		mediaType, _, _ := strings.Cut(contentType, ";")
98		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
99			return nil, ValidationError("Content-Type must be application/json")
100		}
101		body, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
102		if err != nil {
103			return nil, ValidationError("request body could not be read")
104		}
105		if len(body) > maxBodyBytes {
106			return nil, ValidationError("request body must be at most %d bytes", maxBodyBytes)
107		}
108		return body, nil
109	}
110	
111	func splitPath(path string) []string {
112		parts := []string{}
113		for _, part := range strings.Split(path, "/") {
114			if part != "" {
115				parts = append(parts, part)
116			}
117		}
118		return parts
119	}
120	
121	// requireQuery rejects every query parameter that the route does not document.
122	func requireQuery(request *http.Request, allowed ...string) error {
123		names := make([]string, 0, len(request.URL.Query()))
124		for name := range request.URL.Query() {
125			names = append(names, name)
126		}
127		sort.Strings(names)
128		for _, name := range names {
129			known := false
130			for _, candidate := range allowed {
131				if name == candidate {
132					known = true
133					break
134				}
135			}
136			if !known {
137				return ValidationError("unknown query parameter %s", name)
138			}
139		}
140		return nil
141	}
142	
143	// writeError maps a service error onto the documented error body. A trace that
144	// is stored but violates span invariants additionally carries its violations.
145	func writeError(writer http.ResponseWriter, err error) {
146		body := map[string]any{
147			"error": map[string]any{"code": "internal_error", "message": "internal server error"},
148		}
149		status := http.StatusInternalServerError
150		var apiError *Error
151		var invalid *TraceInvalidError
152		switch {
153		case errors.As(err, &invalid):
154			status = http.StatusConflict
155			body = map[string]any{
156				"error": map[string]any{
157					"code":       "trace_invalid",
158					"message":    invalid.Message,
159					"trace_id":   invalid.TraceID,
160					"violations": publicViolations(invalid.Violations),
161				},
162			}
163		case errors.As(err, &apiError):
164			status = apiError.Status
165			body = map[string]any{
166				"error": map[string]any{"code": apiError.Code, "message": apiError.Message},
167			}
168		}
169		writeJSON(writer, status, body)
170	}
171	
172	func writeJSON(writer http.ResponseWriter, status int, value any) {
173		encoded, err := json.Marshal(value)
174		if err != nil {
175			status = http.StatusInternalServerError
176			encoded = []byte(`{"error":{"code":"internal_error","message":"internal server error"}}`)
177		}
178		writer.Header().Set("Content-Type", "application/json; charset=utf-8")
179		writer.Header().Set("Content-Length", strconv.Itoa(len(encoded)))
180		writer.WriteHeader(status)
181		writer.Write(encoded)
182	}
