1	package tracepath
2	
3	import (
4		"net/url"
5		"sort"
6		"strconv"
7		"strings"
8		"time"
9	)
10	
11	// Service implements the TracePath contract on top of a Store. It owns span
12	// ingestion, trace reassembly, critical path analysis, error propagation
13	// marking and the service dependency graph.
14	type Service struct {
15		store *Store
16		clock func() time.Time
17	}
18	
19	// NewService wires a store and an injectable clock.
20	func NewService(store *Store, clock func() time.Time) (*Service, error) {
21		if store == nil {
22			return nil, InternalError("service requires a store")
23		}
24		if clock == nil {
25			clock = time.Now
26		}
27		return &Service{store: store, clock: clock}, nil
28	}
29	
30	func (s *Service) now() string {
31		return s.clock().UTC().Format(idLayout)
32	}
33	
34	// runIdempotent executes action at most once per key. The first response is
35	// re-rendered from committed state for every later request that carries the
36	// same key and the same resource identity, so a replay is byte-identical by
37	// construction. Reusing a key for another operation, or for another resource,
38	// is a conflict.
39	func (s *Service) runIdempotent(key string, operation string, identity string, action func(state *State) (any, error)) (any, error) {
40		if key == "" {
41			return nil, ValidationError("Idempotency-Key header is required")
42		}
43		if len(key) > 200 {
44			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
45		}
46		var response any
47		err := s.store.Update(func(state *State) error {
48			if record, found := state.Idempotency[key]; found {
49				if record.Operation != operation {
50					return ConflictError("idempotency key was already used for another operation")
51				}
52				if record.Identity != identity {
53					return ConflictError("idempotency key was already used for resource %s", record.Identity)
54				}
55				response = identity
56				return nil
57			}
58			value, err := action(state)
59			if err != nil {
60				return err
61			}
62			state.Idempotency[key] = &IdempotencyRecord{
63				Key:       key,
64				Operation: operation,
65				Identity:  identity,
66				CreatedAt: s.now(),
67			}
68			response = value
69			return nil
70		})
71		if err != nil {
72			return nil, err
73		}
74		return response, nil
75	}
76	
77	// spanResponse is the public projection of one ingested span.
78	type spanResponse struct {
79		TraceID    string            `json:"trace_id"`
80		SpanID     string            `json:"span_id"`
81		ParentID   *string           `json:"parent_id"`
82		Service    string            `json:"service"`
83		Operation  string            `json:"operation"`
84		Kind       string            `json:"kind"`
85		StartTime  string            `json:"start_time"`
86		DurationNS int64             `json:"duration_ns"`
87		Status     string            `json:"status"`
88		Attributes map[string]string `json:"attributes"`
89		Accepted   bool              `json:"accepted"`
90		SpanCount  int               `json:"span_count"`
91		Complete   bool              `json:"complete"`
92		Valid      bool              `json:"valid"`
93		Violations []Validation      `json:"violations"`
94	}
95	
96	// renderSpan projects one stored span onto its public projection. The identity
97	// of the projected span is returned as well.
98	func renderSpan(state *State, traceID string, spanID string) (any, error) {
99		spans, found := state.Spans[traceID]
100		if !found {
101			return nil, InternalError("trace %s disappeared during ingestion", traceID)
102		}
103		span, found := spans[spanID]
104		if !found {
105			return nil, InternalError("span %s of trace %s disappeared during ingestion", spanID, traceID)
106		}
107		trace := assembleTrace(traceID, spans)
108		declared := trace.SpanCount
109		if trace.RootSpanCount != 0 {
110			declared = trace.RootSpanCount
111		}
112		response := &spanResponse{
113			TraceID:    span.TraceID,
114			SpanID:     span.SpanID,
115			ParentID:   span.ParentID,
116			Service:    span.Service,
117			Operation:  span.Operation,
118			Kind:       span.Kind,
119			StartTime:  span.StartTime,
120			DurationNS: span.DurationNS,
121			Status:     span.Status,
122			Attributes: map[string]string{},
123			Accepted:   true,
124			SpanCount:  declared,
125			Complete:   trace.Complete,
126			Valid:      trace.Valid,
127			Violations: publicViolations(trace.Violations),
128		}
129		for attribute, value := range span.Attributes {
130			response.Attributes[attribute] = value
131		}
132		return response, nil
133	}
134	
135	// IngestSpan validates and stores one span. Every check that needs the other
136	// spans of the trace (parent existence, trace id agreement, time containment)
137	// runs against the committed state under the store lock.
138	func (s *Service) IngestSpan(body []byte, key string) (any, error) {
139		var input SpanInput
140		if err := decodeObject(body, &input); err != nil {
141			return nil, err
142		}
143		start, err := validateSpanInput(&input)
144		if err != nil {
145			return nil, err
146		}
147		spanID, err := validateIdentifier(input.SpanID, "span_id")
148		if err != nil {
149			return nil, err
150		}
151		traceID, err := validateIdentifier(input.TraceID, "trace_id")
152		if err != nil {
153			return nil, err
154		}
155		operation := "ingest-span"
156		identity := traceID + "/" + spanID
157	
158		if _, err := s.runIdempotent(key, operation, identity, func(state *State) (any, error) {
159			spans, found := state.Spans[traceID]
160			if !found {
161				if parentID := input.ParentID; parentID != nil {
162					if _, elsewhere := findSpan(state, *parentID); elsewhere != nil {
163						return nil, ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
164							spanID, traceID, *parentID, *elsewhere)
165					}
166				}
167				spans = map[string]*SpanInput{}
168				state.Spans[traceID] = spans
169			}
170			if _, duplicate := spans[spanID]; duplicate {
171				return nil, ConflictError("span %s already exists in trace %s", spanID, traceID)
172			}
173			resolved, err := lineOf(spans, &input)
174			if err != nil {
175				return nil, err
176			}
177			if resolved != traceID {
178				return nil, ConflictError("span %s belongs to trace %s but its parent chain resolves to trace %s",
179					spanID, traceID, resolved)
180			}
181			if input.ParentID != nil {
182				parent, found := spans[*input.ParentID]
183				if found {
184					parentStart, _ := parseTime(parent.StartTime, "start_time")
185					parentEnd := parentStart.Add(time.Duration(parent.DurationNS))
186					end := start.Add(time.Duration(input.DurationNS))
187					if start.Before(parentStart) || end.After(parentEnd) {
188						return nil, ConflictError("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
189							spanID, formatTime(start), formatTime(end), parent.SpanID, parent.StartTime, formatTime(parentEnd))
190					}
191				}
192			}
193			clone := input
194			clone.Attributes = map[string]string{}
195			for attribute, value := range input.Attributes {
196				clone.Attributes[attribute] = value
197			}
198			spans[spanID] = &clone
199			return nil, nil
200		}); err != nil {
201			return nil, err
202		}
203		return s.store.View(func(state *State) (any, error) {
204			return renderSpan(state, traceID, spanID)
205		})
206	}
207	
208	// findSpan locates a span id in any trace and returns its trace id.
209	func findSpan(state *State, spanID string) (*SpanInput, *string) {
210		for traceID, spans := range state.Spans {
211			if span, found := spans[spanID]; found {
212				id := traceID
213				return span, &id
214			}
215		}
216		return nil, nil
217	}
218	
219	func publicViolations(violations []Violation) []Validation {
220		public := make([]Validation, 0, len(violations))
221		for _, violation := range violations {
222			public = append(public, Validation{
223				Code:    violation.Code,
224				TraceID: violation.TraceID,
225				SpanID:  violation.SpanID,
226				Message: violation.Message,
227			})
228		}
229		return public
230	}
231	
232	// GetTrace reassembles one trace and fails when it is incomplete or unusable.
233	func (s *Service) GetTrace(traceID string) (any, error) {
234		value, err := s.store.View(func(state *State) (any, error) {
235			spans, found := state.Spans[traceID]
236			if !found {
237				return nil, NotFoundError("trace %s does not exist", traceID)
238			}
239			return assembleTrace(traceID, spans), nil
240		})
241		if err != nil {
242			return nil, err
243		}
244		trace := value.(*Trace)
245		if !trace.Complete {
246			return nil, InvalidTraceError(traceID, append([]Violation{{
247				Code:    "trace_incomplete",
248				TraceID: traceID,
249				SpanID:  "",
250				Message: "trace is not complete yet or its declared span_count does not match the ingested spans",
251			}}, trace.Violations...))
252		}
253		if !trace.Valid {
254			return nil, InvalidTraceError(traceID, trace.Violations)
255		}
256		return trace, nil
257	}
258	
259	// TraceFilter narrows GET /traces. Every condition that is set must hold; a
260	// zero-valued filter keeps every trace. Time and duration fields are present as
261	// pointers so that an unset bound never accidentally matches as zero.
262	type TraceFilter struct {
263		// Query is matched as a Unicode case-insensitive substring of the trace id
264		// or of any span service or operation.
265		Query string
266		// Operation keeps traces that have at least one span with this exact op.
267		Operation string
268		// Service keeps traces that contain this service (the legacy semantics).
269		Service string
270		// Status is "", "error" (at least one error span) or "ok" (no error span).
271		Status string
272		// StartFrom is inclusive and StartTo is exclusive on the root start time.
273		StartFrom *time.Time
274		StartTo   *time.Time
275		// MinDurationNS and MaxDurationNS are both inclusive on the root duration.
276		MinDurationNS *int64
277		MaxDurationNS *int64
278		// Complete and Valid filter on the current reassembly result; nil = unset.
279		Complete *bool
280		Valid    *bool
281		// ServicePath is an ordered chain of two or more service names. A trace
282		// matches when it holds spans s1..sn, each a direct child of the previous
283		// one, whose services equal the chain element by element. Nil means unset.
284		ServicePath []string
285	}
286	
287	// TraceFilterFromQuery parses and validates every documented GET /traces
288	// parameter apart from limit, which the HTTP layer keeps. Unknown parameters
289	// are rejected before this is called. All failures are validation errors.
290	func TraceFilterFromQuery(query url.Values) (*TraceFilter, error) {
291		filter := &TraceFilter{
292			Query:   query.Get("q"),
293			Service: strings.TrimSpace(query.Get("service")),
294		}
295		if raw, present := query.Get("operation"), query.Has("operation"); present {
296			operation := strings.TrimSpace(raw)
297			if operation == "" {
298				return nil, ValidationError("operation must not be empty")
299			}
300			filter.Operation = operation
301		}
302		if query.Has("status") {
303			status := query.Get("status")
304			if status != "ok" && status != "error" {
305				return nil, ValidationError("status must be ok or error")
306			}
307			filter.Status = status
308		}
309		if raw, present := query.Get("start_from"), query.Has("start_from"); present {
310			instant, err := parseTime(raw, "start_from")
311			if err != nil {
312				return nil, err
313			}
314			filter.StartFrom = &instant
315		}
316		if raw, present := query.Get("start_to"), query.Has("start_to"); present {
317			instant, err := parseTime(raw, "start_to")
318			if err != nil {
319				return nil, err
320			}
321			filter.StartTo = &instant
322		}
323		if raw, present := query.Get("min_duration_ns"), query.Has("min_duration_ns"); present {
324			value, err := parseDurationBound(raw, "min_duration_ns")
325			if err != nil {
326				return nil, err
327			}
328			filter.MinDurationNS = &value
329		}
330		if raw, present := query.Get("max_duration_ns"), query.Has("max_duration_ns"); present {
331			value, err := parseDurationBound(raw, "max_duration_ns")
332			if err != nil {
333				return nil, err
334			}
335			filter.MaxDurationNS = &value
336		}
337		if filter.MinDurationNS != nil && filter.MaxDurationNS != nil &&
338			*filter.MinDurationNS > *filter.MaxDurationNS {
339			return nil, ValidationError("min_duration_ns must not be greater than max_duration_ns")
340		}
341		if raw, present := query.Get("complete"), query.Has("complete"); present {
342			value, err := parseBoolean(raw, "complete")
343			if err != nil {
344				return nil, err
345			}
346			filter.Complete = &value
347		}
348		if raw, present := query.Get("valid"), query.Has("valid"); present {
349			value, err := parseBoolean(raw, "valid")
350			if err != nil {
351				return nil, err
352			}
353			filter.Valid = &value
354		}
355		if query.Has("service_path") {
356			path, err := parseServicePath(query["service_path"])
357			if err != nil {
358				return nil, err
359			}
360			filter.ServicePath = path
361		}
362		return filter, nil
363	}
364	
365	const (
366		// maxServicePathItems bounds the number of service_path elements and
367		// maxServicePathName the length of each name.
368		maxServicePathItems = 32
369		maxServicePathName  = 128
370	)
371	
372	// parseServicePath validates the repeated service_path parameter. Names are
373	// kept verbatim because matching is exact, so no whitespace is trimmed.
374	func parseServicePath(names []string) ([]string, error) {
375		if len(names) < 2 || len(names) > maxServicePathItems {
376			return nil, ValidationError("service_path must contain between 2 and %d service names", maxServicePathItems)
377		}
378		for index, name := range names {
379			if name == "" {
380				return nil, ValidationError("service_path names must not be empty")
381			}
382			if len(name) > maxServicePathName {
383				return nil, ValidationError("service_path names must be at most %d characters", maxServicePathName)
384			}
385			if index > 0 && names[index-1] == name {
386				return nil, ValidationError("service_path names must differ from their neighbour")
387			}
388		}
389		return names, nil
390	}
391	
392	// parseDurationBound accepts a decimal non-negative integer with no sign,
393	// exponent or surrounding space.
394	func parseDurationBound(raw string, field string) (int64, error) {
395		if raw == "" || strings.TrimSpace(raw) == "" {
396			return 0, ValidationError("%s must be a decimal non-negative integer", field)
397		}
398		for _, r := range raw {
399			if r < '0' || r > '9' {
400				return 0, ValidationError("%s must be a decimal non-negative integer", field)
401			}
402		}
403		value, err := strconv.ParseInt(raw, 10, 64)
404		if err != nil {
405			return 0, ValidationError("%s must be a decimal non-negative integer", field)
406		}
407		return value, nil
408	}
409	
410	// parseBoolean accepts exactly "true" or "false".
411	func parseBoolean(raw string, field string) (bool, error) {
412		switch raw {
413		case "true":
414			return true, nil
415		case "false":
416			return false, nil
417		default:
418			return false, ValidationError("%s must be true or false", field)
419		}
420	}
421	
422	// matches reports whether one reassembled trace satisfies every set condition.
423	func (f *TraceFilter) matches(trace *Trace) bool {
424		if f.Service != "" {
425			found := false
426			for _, node := range trace.Spans {
427				if node.Service == f.Service {
428					found = true
429					break
430				}
431			}
432			if !found {
433				return false
434			}
435		}
436		if f.Operation != "" {
437			found := false
438			for _, node := range trace.Spans {
439				if node.Operation == f.Operation {
440					found = true
441					break
442				}
443			}
444			if !found {
445				return false
446			}
447		}
448		if f.Query != "" {
449			if !containsFold(trace.TraceID, f.Query) {
450				found := false
451				for _, node := range trace.Spans {
452					if containsFold(node.Service, f.Query) || containsFold(node.Operation, f.Query) {
453						found = true
454						break
455					}
456				}
457				if !found {
458					return false
459				}
460			}
461		}
462		switch f.Status {
463		case "error":
464			if trace.ErrorSpans == 0 {
465				return false
466			}
467		case "ok":
468			if trace.ErrorSpans != 0 {
469				return false
470			}
471		}
472		if f.Complete != nil && trace.Complete != *f.Complete {
473			return false
474		}
475		if f.Valid != nil && trace.Valid != *f.Valid {
476			return false
477		}
478		if len(f.ServicePath) > 0 && !matchServicePath(trace.Spans, f.ServicePath) {
479			return false
480		}
481		if f.StartFrom != nil || f.StartTo != nil || f.MinDurationNS != nil || f.MaxDurationNS != nil {
482			// Every time and duration bound refers to the root. A trace without a
483			// root has neither a root instant nor a root duration, so any such
484			// bound excludes it.
485			if trace.Root == nil {
486				return false
487			}
488		}
489		if f.StartFrom != nil || f.StartTo != nil {
490			rootStart, err := parseTime(trace.Root.StartTime, "start_time")
491			if err != nil {
492				return false
493			}
494			if f.StartFrom != nil && rootStart.Before(*f.StartFrom) {
495				return false
496			}
497			if f.StartTo != nil && !rootStart.Before(*f.StartTo) {
498				return false
499			}
500		}
501		if f.MinDurationNS != nil && trace.DurationNS < *f.MinDurationNS {
502			return false
503		}
504		if f.MaxDurationNS != nil && trace.DurationNS > *f.MaxDurationNS {
505			return false
506		}
507		return true
508	}
509	
510	// matchServicePath reports whether the reassembled span tree contains a chain
511	// of direct parent/child spans whose services equal path element by element.
512	// The chain may start at any span; only the stored parent/child links are
513	// consulted, so an incomplete or invalid trace is judged on the spans it has.
514	func matchServicePath(nodes []*TraceNode, path []string) bool {
515		for _, node := range nodes {
516			if matchServicePathFrom(node, path, 0) {
517				return true
518			}
519		}
520		return false
521	}
522	
523	func matchServicePathFrom(node *TraceNode, path []string, index int) bool {
524		if node.Service != path[index] {
525			return false
526		}
527		if index == len(path)-1 {
528			return true
529		}
530		for _, child := range node.Children {
531			if matchServicePathFrom(child, path, index+1) {
532				return true
533			}
534		}
535		return false
536	}
537	
538	// ListTraces summarises every stored trace with at least one span.
539	func (s *Service) ListTraces(filter *TraceFilter, limit int) (any, error) {
540		if limit < 1 || limit > 400 {
541			return nil, ValidationError("limit must be between 1 and 400")
542		}
543		if filter == nil {
544			filter = &TraceFilter{}
545		}
546		value, err := s.store.View(func(state *State) (any, error) {
547			summaries := []*TraceSummary{}
548			for _, traceID := range state.traceIDs() {
549				trace := assembleTrace(traceID, state.Spans[traceID])
550				if !filter.matches(trace) {
551					continue
552				}
553				summary := &TraceSummary{
554					TraceID:      trace.TraceID,
555					StartTime:    "",
556					DurationNS:   trace.DurationNS,
557					SpanCount:    trace.SpanCount,
558					ServiceCount: trace.ServiceCount,
559					ErrorSpans:   trace.ErrorSpans,
560					Complete:     trace.Complete,
561					Valid:        trace.Valid,
562				}
563				if trace.Root != nil {
564					rootID := trace.Root.SpanID
565					rootService := trace.Root.Service
566					summary.RootSpanID = &rootID
567					summary.RootService = &rootService
568					summary.StartTime = trace.Root.StartTime
569					summary.rootInstant, _ = parseTime(trace.Root.StartTime, "start_time")
570				}
571				summaries = append(summaries, summary)
572			}
573			sort.Slice(summaries, func(i, j int) bool {
574				if !summaries[i].rootInstant.Equal(summaries[j].rootInstant) {
575					return summaries[i].rootInstant.After(summaries[j].rootInstant)
576				}
577				return summaries[i].TraceID < summaries[j].TraceID
578			})
579			if len(summaries) > limit {
580				summaries = summaries[:limit]
581			}
582			return map[string]any{"traces": summaries}, nil
583		})
584		if err != nil {
585			return nil, err
586		}
587		return value, nil
588	}
589	
590	// CriticalPath walks the root-to-leaf path with the largest total self_time. It
591	// therefore needs time containment to hold, exactly like the invariant
592	// "critical path length equals the root span duration" does.
593	func (s *Service) CriticalPath(traceID string) (any, error) {
594		value, err := s.store.View(func(state *State) (any, error) {
595			spans, found := state.Spans[traceID]
596			if !found {
597				return nil, NotFoundError("trace %s does not exist", traceID)
598			}
599			return assembleTrace(traceID, spans), nil
600		})
601		if err != nil {
602			return nil, err
603		}
604		trace := value.(*Trace)
605		path := &CriticalPath{
606			TraceID:         traceID,
607			Method:          "longest chain below the root, weighted by self_time_ns; ties are broken by the longest sub-chain and then by the smallest span id sequence",
608			TraceDurationNS: trace.DurationNS,
609			Path:            []PathStep{},
610			Complete:        trace.Complete,
611			Valid:           trace.Valid || trace.Root == nil,
612			Violations:      publicViolations(trace.Violations),
613		}
614		if !trace.Complete {
615			path.Valid = false
616		}
617		if trace.Root == nil {
618			return path, nil
619		}
620		_, steps := longestSelfTimePath(trace.Root)
621		path.Path = steps
622		for _, step := range steps {
623			path.LengthNS += step.SelfTimeNS
624		}
625		return path, nil
626	}
627	
628	type pathCandidate struct {
629		// weight is the sum of self_time along the candidate: the value the response
630		// reports as the length of the path.
631		weight int64
632		// path is the longest self_time-weighted path of the subtree, used to break a
633		// tie between two branches that weigh the same.
634		path  int64
635		steps int
636		ids   []string
637	}
638	
639	// better ranks two candidates of the same node. More self_time wins. An equal
640	// weight is settled by the branch with the longer critical path, then by the
641	// shorter path, then by the lexicographically smallest span id sequence, so the
642	// output is deterministic.
643	func better(candidate pathCandidate, incumbent pathCandidate) bool {
644		if candidate.weight != incumbent.weight {
645			return candidate.weight > incumbent.weight
646		}
647		if candidate.path != incumbent.path {
648			return candidate.path > incumbent.path
649		}
650		if candidate.steps != incumbent.steps {
651			return candidate.steps < incumbent.steps
652		}
653		for index := 0; index < len(candidate.ids) && index < len(incumbent.ids); index++ {
654			if candidate.ids[index] != incumbent.ids[index] {
655				return candidate.ids[index] < incumbent.ids[index]
656			}
657		}
658		return len(candidate.ids) < len(incumbent.ids)
659	}
660	
661	// longestSelfTimePath returns the winning candidate of the subtree together
662	// with the steps of the critical path, both in pre-order. The tree builder has
663	// already computed maxPath for every span, so the winner is the child whose
664	// maxPath is the largest and the weight of the result is this node's maxPath.
665	func longestSelfTimePath(node *TraceNode) (pathCandidate, []PathStep) {
666		self := PathStep{
667			SpanID:     node.SpanID,
668			ParentID:   node.ParentID,
669			Service:    node.Service,
670			Operation:  node.Operation,
671			Depth:      node.Depth,
672			SelfTimeNS: node.SelfTimeNS,
673			StartTime:  node.StartTime,
674			EndTime:    node.EndTime,
675		}
676		best := pathCandidate{weight: node.SelfTimeNS, path: node.maxPath, steps: 1, ids: []string{node.SpanID}}
677		var bestSteps []PathStep
678		for _, child := range node.Children {
679			candidate, steps := longestSelfTimePath(child)
680			candidate.weight += node.SelfTimeNS
681			candidate.steps++
682			candidate.ids = append([]string{node.SpanID}, candidate.ids...)
683			if bestSteps == nil || better(candidate, best) {
684				best = candidate
685				bestSteps = steps
686			}
687		}
688		if bestSteps == nil {
689			bestSteps = []PathStep{}
690		}
691		steps := append([]PathStep{self}, bestSteps...)
692		weight := int64(0)
693		for _, item := range steps {
694			weight += item.SelfTimeNS
695		}
696		best.weight = weight
697		if best.weight < node.maxPath {
698			best.weight = node.maxPath
699		}
700		return best, steps
701	}
702	
703	// ServiceGraph aggregates the caller/callee graph. traceID limits the analysis
704	// to one trace; an empty traceID covers every stored trace.
705	func (s *Service) ServiceGraph(traceID string) (any, error) {
706		value, err := s.store.View(func(state *State) (any, error) {
707			graph := &ServiceGraph{
708				Services: []*ServiceStat{},
709				Edges:    []*ServiceEdge{},
710				Stats:    &GraphStats{},
711			}
712			ids := state.traceIDs()
713			if traceID != "" {
714				if _, found := state.Spans[traceID]; !found {
715					return nil, NotFoundError("trace %s does not exist", traceID)
716				}
717				ids = []string{traceID}
718				// The response always echoes an explicitly requested trace.
719				graph.TraceID = &ids[0]
720			}
721			services := map[string]*ServiceStat{}
722			edges := map[string]*ServiceEdge{}
723			graph.Stats.durations = []int64{}
724			for _, id := range ids {
725				trace := assembleTrace(id, state.Spans[id])
726				usable := trace.Valid && trace.Complete && trace.Root != nil
727				if !usable {
728					if traceID != "" {
729						// An explicitly requested trace is reported as-is, complete
730						// or not.
731						graph.Stats.PartialTraces = 1
732						return graph, nil
733					}
734					graph.Stats.PartialTraces++
735					continue
736				}
737				graph.Stats.TraceCount++
738				graph.Stats.SpanCount += trace.SpanCount
739				graph.Stats.ErrorSpans += trace.ErrorSpans
740				graph.Stats.durations = append(graph.Stats.durations, trace.DurationNS)
741				for _, node := range trace.Spans {
742					stat := services[node.Service]
743					if stat == nil {
744						stat = &ServiceStat{Service: node.Service, Operations: []*OperationStat{}, durations: []int64{}}
745						services[node.Service] = stat
746					}
747					stat.SpanCount++
748					stat.SelfTimeNS += node.SelfTimeNS
749					stat.durations = append(stat.durations, node.DurationNS)
750					if node.Error {
751						stat.ErrorSpans++
752					}
753					if node.ParentID == nil {
754						stat.RootSpans++
755					}
756					operation := operationStat(stat, node.Operation)
757					operation.SpanCount++
758					operation.SelfTimeNS += node.SelfTimeNS
759					operation.durations = append(operation.durations, node.DurationNS)
760					if node.Error {
761						operation.ErrorSpans++
762					}
763				}
764				byID := map[string]*TraceNode{}
765				for _, node := range trace.Spans {
766					byID[node.SpanID] = node
767				}
768				for _, node := range trace.Spans {
769					if node.ParentID == nil {
770						continue
771					}
772					parent := byID[*node.ParentID]
773					if parent == nil || parent.Service == node.Service {
774						continue
775					}
776					key := parent.Service + "\x00" + node.Service
777					edge := edges[key]
778					if edge == nil {
779						edge = &ServiceEdge{Caller: parent.Service, Callee: node.Service, durations: []int64{}}
780						edges[key] = edge
781					}
782					edge.CallCount++
783					edge.durations = append(edge.durations, node.DurationNS)
784					if node.Error {
785						edge.ErrorCount++
786					}
787				}
788			}
789			for _, stat := range services {
790				finalizeService(stat)
791				graph.Services = append(graph.Services, stat)
792			}
793			for _, edge := range edges {
794				finalizeEdge(edge)
795				graph.Edges = append(graph.Edges, edge)
796			}
797			sort.Slice(graph.Services, func(i, j int) bool { return graph.Services[i].Service < graph.Services[j].Service })
798			sort.Slice(graph.Edges, func(i, j int) bool {
799				if graph.Edges[i].Caller != graph.Edges[j].Caller {
800					return graph.Edges[i].Caller < graph.Edges[j].Caller
801				}
802				return graph.Edges[i].Callee < graph.Edges[j].Callee
803			})
804			finalizeStats(graph.Stats)
805			return graph, nil
806		})
807		if err != nil {
808			return nil, err
809		}
810		return value, nil
811	}
812	
813	func operationStat(service *ServiceStat, operation string) *OperationStat {
814		for _, stat := range service.Operations {
815			if stat.Operation == operation {
816				return stat
817			}
818		}
819		stat := &OperationStat{Operation: operation, durations: []int64{}}
820		service.Operations = append(service.Operations, stat)
821		return stat
822	}
823	
824	func finalizeService(stat *ServiceStat) {
825		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
826		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
827		stat.MeanDurationNS = mean(stat.durations)
828		stat.P50DurationNS = percentile(stat.durations, 50)
829		stat.P95DurationNS = percentile(stat.durations, 95)
830		stat.durations = nil
831		sort.Slice(stat.Operations, func(i, j int) bool { return stat.Operations[i].Operation < stat.Operations[j].Operation })
832		for _, operation := range stat.Operations {
833			finalizeOperation(operation)
834		}
835	}
836	
837	func finalizeOperation(stat *OperationStat) {
838		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
839		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
840		stat.MeanDurationNS = mean(stat.durations)
841		stat.P50DurationNS = percentile(stat.durations, 50)
842		stat.P95DurationNS = percentile(stat.durations, 95)
843		stat.durations = nil
844	}
845	
846	func finalizeEdge(edge *ServiceEdge) {
847		sort.Slice(edge.durations, func(i, j int) bool { return edge.durations[i] < edge.durations[j] })
848		edge.MinDurationNS, edge.MaxDurationNS = bounds(edge.durations)
849		edge.MeanDurationNS = mean(edge.durations)
850		edge.P50DurationNS = percentile(edge.durations, 50)
851		edge.P95DurationNS = percentile(edge.durations, 95)
852		edge.durations = nil
853	}
854	
855	func finalizeStats(stats *GraphStats) {
856		sort.Slice(stats.durations, func(i, j int) bool { return stats.durations[i] < stats.durations[j] })
857		stats.DurationNS, _ = bounds(stats.durations)
858		stats.MeanDurationNS = mean(stats.durations)
859		stats.P50DurationNS = percentile(stats.durations, 50)
860		stats.P95DurationNS = percentile(stats.durations, 95)
861		stats.durations = nil
862	}
863	
864	func bounds(sorted []int64) (int64, int64) {
865		if len(sorted) == 0 {
866			return 0, 0
867		}
868		return sorted[0], sorted[len(sorted)-1]
869	}
870	
871	func mean(sorted []int64) int64 {
872		if len(sorted) == 0 {
873			return 0
874		}
875		total := int64(0)
876		for _, value := range sorted {
877			total += value
878		}
879		return total / int64(len(sorted))
880	}
881	
882	// percentile uses the nearest-rank definition on already sorted input:
883	// index = ceil(p/100 * n) - 1. Input is never mutated.
884	func percentile(sorted []int64, p int) int64 {
885		if len(sorted) == 0 {
886			return 0
887		}
888		rank := (p*len(sorted) + 99) / 100
889		if rank < 1 {
890			rank = 1
891		}
892		if rank > len(sorted) {
893			rank = len(sorted)
894		}
895		return sorted[rank-1]
896	}
897	
898	func sortStrings(values []string) {
899		sort.Strings(values)
900	}
901

