1	package tracepath
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"sort"
9		"strings"
10		"time"
11		"unicode"
12	)
13	
14	const (
15		// idLayout is the timestamp format accepted on input and produced on output.
16		// It is time.RFC3339Nano trimmed of trailing zeros, so "…T00:00:00Z" stays
17		// readable while "…T00:00:00.000000001Z" keeps nanosecond precision.
18		idLayout = "2006-01-02T15:04:05.999999999Z07:00"
19	
20		maxIdentifierLength = 64
21		maxTextLength       = 128
22		maxAttributeCount   = 32
23		maxAttributeKey     = 64
24		maxAttributeValue   = 512
25		maxSpanCount        = 100000
26		maxBodyBytes        = 1 << 20
27	)
28	
29	// spanKinds is the closed set of span kinds.
30	var spanKinds = map[string]bool{
31		"internal": true,
32		"server":   true,
33		"client":   true,
34		"producer": true,
35		"consumer": true,
36	}
37	
38	// spanStatuses is the closed set of span statuses.
39	var spanStatuses = map[string]bool{"ok": true, "error": true}
40	
41	// SpanInput is one ingested span exactly as it arrived. The raw strings are
42	// kept verbatim so that persisted state round-trips byte for byte.
43	type SpanInput struct {
44		TraceID    string            `json:"trace_id"`
45		SpanID     string            `json:"span_id"`
46		ParentID   *string           `json:"parent_id"`
47		Service    string            `json:"service"`
48		Operation  string            `json:"operation"`
49		Kind       string            `json:"kind"`
50		StartTime  string            `json:"start_time"`
51		DurationNS int64             `json:"duration_ns"`
52		Status     string            `json:"status"`
53		Attributes map[string]string `json:"attributes"`
54		SpanCount  *int              `json:"span_count"`
55	}
56	
57	// IdempotencyRecord stores which resource the first request with a key created.
58	// The response body is re-rendered from state on every replay, so the recorded
59	// identity is enough to detect a key reused for a different operation.
60	type IdempotencyRecord struct {
61		Key       string `json:"key"`
62		Operation string `json:"operation"`
63		Identity  string `json:"identity"`
64		CreatedAt string `json:"created_at"`
65	}
66	
67	// Violation is one structural error found while assembling a trace.
68	type Violation struct {
69		Code    string `json:"code"`
70		TraceID string `json:"trace_id"`
71		SpanID  string `json:"span_id"`
72		Message string `json:"message"`
73	}
74	
75	// TraceNode is one span of the reassembled tree with its derived timing. The
76	// declared duration is never rewritten; timing violations are reported instead.
77	type TraceNode struct {
78		TraceID    string  `json:"trace_id"`
79		SpanID     string  `json:"span_id"`
80		ParentID   *string `json:"parent_id"`
81		Service    string  `json:"service"`
82		Operation  string  `json:"operation"`
83		Kind       string  `json:"kind"`
84		Status     string  `json:"status"`
85		StartTime  string  `json:"start_time"`
86		EndTime    string  `json:"end_time"`
87		DurationNS int64   `json:"duration_ns"`
88		SelfTimeNS int64   `json:"self_time_ns"`
89		// TotalDurationNS is the duration of the whole subtree of this span, derived
90		// from the declared values rather than from wall-clock arithmetic.
91		TotalDurationNS int64 `json:"subtree_duration_ns"`
92		// maxPath is the longest self_time-weighted path from this span downwards. It
93		// is internal bookkeeping and equals the span duration by construction.
94		maxPath      int64
95		Depth        int               `json:"depth"`
96		Error        bool              `json:"error"`
97		ErrorOrigin  bool              `json:"error_origin"`
98		Propagated   bool              `json:"propagated"`
99		ErrorOrigins []string          `json:"error_origins"`
100		Attributes   map[string]string `json:"attributes"`
101		Children     []*TraceNode      `json:"children"`
102	}
103	
104	// assignTiming derives self_time and the critical path of one subtree.
105	//
106	// LongestPath(t) is the largest sum of self_time on any path from t downwards.
107	// The critical branch K is the child with the largest LongestPath. self_time(t)
108	// is then everything of t's duration that K does not account for:
109	// duration(t) - LongestPath(K), where a leaf is its own critical branch. That
110	// makes self_time exactly the exclusive time off the critical path, so the self
111	// times along the critical path add up to duration(t), which is the invariant
112	// this service promises.
113	//
114	// Children are independent of each other, so LongestPath(child) can be computed
115	// before self_time(t) and does not change afterwards.
116	func assignTiming(node *TraceNode) {
117		if len(node.Children) == 0 {
118			node.SelfTimeNS = node.DurationNS
119			node.maxPath = node.DurationNS
120			return
121		}
122		critical := node.Children[0]
123		for _, child := range node.Children {
124			assignTiming(child)
125			if child.maxPath > critical.maxPath {
126				critical = child
127			}
128		}
129		selfTime := node.DurationNS - critical.maxPath
130		if selfTime < 0 {
131			selfTime = 0
132		}
133		node.SelfTimeNS = selfTime
134		node.maxPath = selfTime + critical.maxPath
135		if node.maxPath > node.DurationNS {
136			node.maxPath = node.DurationNS
137		}
138	}
139	
140	// Trace is a fully reassembled trace. Valid is false when Violations is not
141	// empty; the tree is still returned so a caller can inspect the damage.
142	type Trace struct {
143		TraceID       string       `json:"trace_id"`
144		Root          *TraceNode   `json:"root"`
